-- Yappa: reviewed word cards (category, difficulty, off-limits words, components, variants).
-- Generated by scripts/words/to-sql.mjs from the hand-reviewed words.review.json.
-- Pool after this: 167 Easy, 183 Medium, 88 Hard.
-- By category: Tools & Gadgets 28, Music 32, Buildings 42, Animals 53, Food & Drink 54, Sports 50, Nature 32, Around the House 27, Pop Culture 40, Fairy Tales 40, Video Games 40.

alter table words add column if not exists forbidden text[] not null default '{}';

delete from words where id in ('tooth-fairy', 'hansel-and-gretel', 'zelda', 'fifa', 'donkey-kong', 'space-invaders');

insert into words (id, word, category, difficulty) values ('humpty-dumpty', 'Humpty Dumpty', 'Fairy Tales', 'medium') on conflict (word) do nothing;
insert into words (id, word, category, difficulty) values ('ugly-duckling', 'Ugly Duckling', 'Fairy Tales', 'medium') on conflict (word) do nothing;
insert into words (id, word, category, difficulty) values ('call-of-duty', 'Call of Duty', 'Video Games', 'medium') on conflict (word) do nothing;
